args.Content:
:root {
  --bg-primary: #090e1a;
  --bg-secondary: #111827;
  --bg-card: #161f33;
  --bg-glass: rgba(15, 23, 42, 0.78);
  --border-subtle: rgba(148, 163, 184, 0.18);
  --border-gold: rgba(245, 158, 11, 0.45);
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --accent: #f59e0b;
  --accent-hover: #fbbf24;
  --accent-soft: rgba(245, 158, 11, 0.14);
  --interior: #38bdf8;
  --exterior: #34d399;
  --danger: #ef4444;
  --radius: 14px;
  --shadow: 0 20px 45px rgba(0, 0, 0, 0.45);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  font-family: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  min-height: 100%;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

button, input, select, textarea {
  font-family: inherit;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 18px;
  border-radius: 10px;
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-primary);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
}

.btn:hover {
  background: rgba(255, 255, 255, 0.12);
  transform: translateY(-1px);
}

.btn-primary {
  background: linear-gradient(135deg, #f59e0b, #d97706);
  color: #0b1120;
  border-color: transparent;
}

.btn-primary:hover {
  background: linear-gradient(135deg, #fbbf24, #f59e0b);
}

.btn-danger {
  background: rgba(239, 68, 68, 0.15);
  color: #fca5a5;
  border-color: rgba(239, 68, 68, 0.35);
}

.btn-danger:hover {
  background: rgba(239, 68, 68, 0.28);
}

.btn-sm {
  padding: 6px 12px;
  font-size: 0.8rem;
  border-radius: 8px;
}

.btn-icon {
  width: 40px;
  height: 40px;
  padding: 0;
  border-radius: 10px;
}

.btn.active {
  background: var(--accent-soft);
  border-color: var(--accent);
  color: var(--accent-hover);
}

/* ---------- Landing / Project Showcase ---------- */
.navbar {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(9, 14, 26, 0.85);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border-subtle);
}

.navbar-inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: -0.02em;
}

.brand-badge {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: linear-gradient(135deg, #f59e0b, #b45309);
  color: #090e1a;
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 0.9rem;
}

.hero {
  max-width: 1240px;
  margin: 0 auto;
  padding: 48px 24px 28px;
}

.hero-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  border-radius: 999px;
  background: var(--accent-soft);
  border: 1px solid var(--border-gold);
  color: var(--accent-hover);
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: 16px;
}

.hero h1 {
  font-size: clamp(1.8rem, 3.8vw, 2.9rem);
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 12px;
}

.hero p {
  color: var(--text-secondary);
  max-width: 660px;
  font-size: 1.02rem;
  line-height: 1.6;
}

.projects-grid {
  max-width: 1240px;
  margin: 0 auto;
  padding: 16px 24px 64px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(330px, 1fr));
  gap: 24px;
}

.project-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease;
}

.project-card:hover {
  transform: translateY(-4px);
  border-color: var(--border-gold);
  box-shadow: var(--shadow);
}

.project-thumb {
  position: relative;
  height: 210px;
  background: #0f172a;
  overflow: hidden;
}

.project-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.project-card:hover .project-thumb img {
  transform: scale(1.04);
}

.project-badge-360 {
  position: absolute;
  top: 12px;
  left: 12px;
  padding: 5px 10px;
  border-radius: 8px;
  background: rgba(9, 14, 26, 0.8);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-gold);
  color: var(--accent-hover);
  font-size: 0.75rem;
  font-weight: 700;
}

.project-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
}

.project-title {
  font-size: 1.2rem;
  font-weight: 700;
}

.project-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 0.84rem;
  color: var(--text-secondary);
}

.project-desc {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.5;
  flex: 1;
}

.project-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-top: 12px;
  border-top: 1px solid var(--border-subtle);
}

.price-tag {
  font-weight: 700;
  color: var(--accent-hover);
  font-size: 0.95rem;
}

/* ---------- 360 VR Viewer ---------- */
.viewer-shell {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #000;
  user-select: none;
}

#pano-canvas-container {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

#hotspots-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 10;
}

.hotspot-marker {
  position: absolute;
  transform: translate(-50%, -50%);
  pointer-events: auto;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  transition: opacity 0.15s ease;
}

.hotspot-dot {
  width: 42px;
  height: 42px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.85);
  border: 2px solid var(--accent-hover);
  color: var(--accent-hover);
  display: grid;
  place-items: center;
  box-shadow: 0 0 0 6px rgba(245, 158, 11, 0.2), 0 8px 20px rgba(0, 0, 0, 0.5);
  animation: pulseRing 2.2s infinite;
  transition: transform 0.2s ease, background 0.2s ease;
}

.hotspot-marker:hover .hotspot-dot {
  transform: scale(1.14);
  background: var(--accent);
  color: #090e1a;
}

.hotspot-label {
  padding: 5px 11px;
  border-radius: 8px;
  background: rgba(9, 14, 26, 0.88);
  border: 1px solid var(--border-subtle);
  color: #fff;
  font-size: 0.78rem;
  font-weight: 600;
  white-space: nowrap;
  backdrop-filter: blur(8px);
}

@keyframes pulseRing {
  0% { box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.45), 0 8px 20px rgba(0, 0, 0, 0.5); }
  70% { box-shadow: 0 0 0 12px rgba(245, 158, 11, 0), 0 8px 20px rgba(0, 0, 0, 0.5); }
  100% { box-shadow: 0 0 0 0 rgba(245, 158, 11, 0), 0 8px 20px rgba(0, 0, 0, 0.5); }
}

.viewer-topbar {
  position: absolute;
  top: 16px;
  left: 16px;
  right: 16px;
  z-index: 20;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  pointer-events: none;
}

.viewer-topbar > * {
  pointer-events: auto;
}

.viewer-title-card {
  background: var(--bg-glass);
  backdrop-filter: blur(14px);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: min(460px, 70vw);
}

.viewer-title-text h2 {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.2;
}

.viewer-title-text p {
  font-size: 0.78rem;
  color: var(--text-secondary);
  margin-top: 2px;
}

.viewer-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  background: var(--bg-glass);
  backdrop-filter: blur(14px);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 6px;
}

/* ---------- Floorplan Minimap ---------- */
.minimap-widget {
  position: absolute;
  right: 16px;
  bottom: 96px;
  z-index: 25;
  width: min(310px, 42vw);
  background: var(--bg-glass);
  backdrop-filter: blur(16px);
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: width 0.25s ease, transform 0.25s ease;
}

.minimap-widget.expanded {
  width: min(520px, 88vw);
}

.minimap-widget.collapsed .minimap-body {
  display: none;
}

.minimap-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 12px;
  border-bottom: 1px solid var(--border-subtle);
  font-size: 0.8rem;
  font-weight: 700;
}

.minimap-header-actions {
  display: flex;
  gap: 6px;
}

.minimap-body {
  padding: 10px;
}

.floorplan-stage {
  position: relative;
  width: 100%;
  border-radius: 10px;
  overflow: hidden;
  background: #f8fafc;
}

.floorplan-stage img {
  display: block;
  width: 100%;
  height: auto;
  user-select: none;
  pointer-events: none;
}

.floorplan-pin {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 18px;
  height: 18px;
  border-radius: 999px;
  border: 2.5px solid #fff;
  background: #334155;
  cursor: pointer;
  z-index: 3;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.45);
  transition: transform 0.18s ease, background 0.18s ease;
}

.floorplan-pin.interior {
  background: #0284c7;
}

.floorplan-pin.exterior {
  background: #059669;
}

.floorplan-pin:hover {
  transform: translate(-50%, -50%) scale(1.22);
}

.floorplan-pin.active {
  width: 22px;
  height: 22px;
  background: #f59e0b;
  border-color: #090e1a;
  z-index: 5;
  box-shadow: 0 0 0 6px rgba(245, 158, 11, 0.35), 0 3px 10px rgba(0, 0, 0, 0.5);
}

.floorplan-pin-tooltip {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%);
  background: rgba(9, 14, 26, 0.92);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 600;
  padding: 3px 7px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s ease;
}

.floorplan-pin:hover .floorplan-pin-tooltip,
.floorplan-pin.active .floorplan-pin-tooltip {
  opacity: 1;
}

/* Compass / Radar Cone */
.radar-cone {
  position: absolute;
  width: 72px;
  height: 72px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 2;
}

.radar-cone svg {
  width: 100%;
  height: 100%;
  transform-origin: 50% 50%;
}

.minimap-legend {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 8px;
  font-size: 0.72rem;
  color: var(--text-secondary);
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.legend-dot {
  width: 9px;
  height: 9px;
  border-radius: 999px;
}

/* ---------- Bottom Room Strip ---------- */
.viewer-bottombar {
  position: absolute;
  left: 16px;
  right: 16px;
  bottom: 16px;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  pointer-events: none;
}

.room-strip {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  max-width: 100%;
  padding: 6px;
  background: var(--bg-glass);
  backdrop-filter: blur(14px);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
}

.room-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-primary);
  font-size: 0.84rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.18s ease;
}

.room-chip:hover {
  background: rgba(255, 255, 255, 0.12);
}

.room-chip.active {
  background: var(--accent-soft);
  border-color: var(--accent);
  color: var(--accent-hover);
}

.cat-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
}

.cat-dot.interior { background: var(--interior); }
.cat-dot.exterior { background: var(--exterior); }

/* VR Split-Screen Reticle & Exit */
.vr-overlay-hud {
  position: fixed;
  inset: 0;
  z-index: 40;
  pointer-events: none;
  display: none;
}

.vr-overlay-hud.active {
  display: block;
}

.vr-divider {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 2px;
  background: rgba(255, 255, 255, 0.35);
}

.vr-exit-btn {
  position: absolute;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  pointer-events: auto;
}

/* ---------- Admin Panel ---------- */
.admin-login-wrap {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
}

.admin-login-card {
  width: 100%;
  max-width: 420px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 18px;
  padding: 32px;
  box-shadow: var(--shadow);
}

.admin-layout {
  max-width: 1320px;
  margin: 0 auto;
  padding: 24px;
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 24px;
  align-items: start;
}

.panel-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  padding: 20px;
}

.panel-title {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-group.full {
  grid-column: 1 / -1;
}

.form-group label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.input, select.input, textarea.input {
  width: 100%;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--border-subtle);
  background: rgba(9, 14, 26, 0.75);
  color: var(--text-primary);
  font-size: 0.9rem;
  outline: none;
}

.input:focus {
  border-color: var(--accent);
}

.project-list-item {
  padding: 12px;
  border-radius: 12px;
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.03);
  cursor: pointer;
  transition: all 0.16s ease;
  margin-bottom: 10px;
}

.project-list-item.active {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.room-list-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.03);
  margin-bottom: 8px;
}

.room-list-row.active {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.visual-editor-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin-top: 16px;
}

.editor-floorplan-box {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  border: 2px dashed var(--border-gold);
  cursor: crosshair;
  background: #f8fafc;
}

.editor-floorplan-box img {
  display: block;
  width: 100%;
  height: auto;
  pointer-events: none;
}

.editor-pano-box {
  position: relative;
  height: 340px;
  border-radius: 12px;
  overflow: hidden;
  border: 2px dashed var(--border-gold);
  background: #000;
}

.toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 100;
  padding: 12px 18px;
  border-radius: 12px;
  background: #0f172a;
  border: 1px solid var(--accent);
  color: #fff;
  font-size: 0.88rem;
  font-weight: 600;
  box-shadow: var(--shadow);
  display: none;
}

.toast.show {
  display: block;
}

@media (max-width: 960px) {
  .admin-layout {
    grid-template-columns: 1fr;
  }
  .visual-editor-grid {
    grid-template-columns: 1fr;
  }
  .minimap-widget {
    width: min(230px, 52vw);
    bottom: 86px;
  }
}

@media (max-width: 640px) {
  .form-grid {
    grid-template-columns: 1fr;
  }
  .viewer-title-card {
    max-width: 62vw;
    padding: 8px 10px;
  }
}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

/**
 * Reusable Three.js 360° Panorama + VR Stereo + Gyroscope + Hotspot Viewer
 */
export class PanoViewer {
  constructor(container, hotspotsLayer, options = {}) {
    this.container = container;
    this.hotspotsLayer = hotspotsLayer;
    this.options = options;

    this.lon = 0; // yaw in degrees
    this.lat = 0; // pitch in degrees
    this.fov = 75;
    this.autoRotate = false;
    this.stereoMode = false;
    this.gyroEnabled = false;
    this.hotspots = [];
    this.hotspotElements = [];

    this.isPointerDown = false;
    this.pointerDownX = 0;
    this.pointerDownY = 0;
    this.onPointerDownLon = 0;
    this.onPointerDownLat = 0;
    this.movedDistance = 0;

    this._initThree();
    this._bindEvents();
    this._animate();
  }

  _initThree() {
    const width = this.container.clientWidth || window.innerWidth;
    const height = this.container.clientHeight || window.innerHeight;

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(this.fov, width / height, 1, 1100);
    this.cameraLeft = new THREE.PerspectiveCamera(this.fov, (width / 2) / height, 1, 1100);
    this.cameraRight = new THREE.PerspectiveCamera(this.fov, (width / 2) / height, 1, 1100);

    const geometry = new THREE.SphereGeometry(500, 60, 40);
    geometry.scale(-1, 1, 1);

    this.material = new THREE.MeshBasicMaterial({ color: 0xffffff });
    this.sphere = new THREE.Mesh(geometry, this.material);
    this.scene.add(this.sphere);

    this.renderer = new THREE.WebGLRenderer({ antialias: true });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.setSize(width, height);
    this.container.innerHTML = '';
    this.container.appendChild(this.renderer.domElement);

    this.textureLoader = new THREE.TextureLoader();
    this.textureLoader.setCrossOrigin('anonymous');
  }

  _bindEvents() {
    const el = this.renderer.domElement;

    this._onPointerDown = (e) => {
      this.isPointerDown = true;
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;
      this.pointerDownX = clientX;
      this.pointerDownY = clientY;
      this.onPointerDownLon = this.lon;
      this.onPointerDownLat = this.lat;
      this.movedDistance = 0;
    };

    this._onPointerMove = (e) => {
      if (!this.isPointerDown) return;
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;
      const dx = clientX - this.pointerDownX;
      const dy = clientY - this.pointerDownY;
      this.movedDistance = Math.hypot(dx, dy);
      this.lon = (this.pointerDownX - clientX) * 0.16 + this.onPointerDownLon;
      this.lat = (clientY - this.pointerDownY) * 0.16 + this.onPointerDownLat;
      this.lat = Math.max(-85, Math.min(85, this.lat));
    };

    this._onPointerUp = (e) => {
      if (!this.isPointerDown) return;
      this.isPointerDown = false;

      // Treat as click/tap if pointer didn't drag
      if (this.movedDistance < 6 && typeof this.options.onPickPoint === 'function') {
        const rect = el.getBoundingClientRect();
        const clientX = e.changedTouches ? e.changedTouches[0].clientX : e.clientX;
        const clientY = e.changedTouches ? e.changedTouches[0].clientY : e.clientY;
        const ndcX = ((clientX - rect.left) / rect.width) * 2 - 1;
        const ndcY = -((clientY - rect.top) / rect.height) * 2 + 1;

        const raycaster = new THREE.Raycaster();
        raycaster.setFromCamera(new THREE.Vector2(ndcX, ndcY), this.camera);
        const intersects = raycaster.intersectObject(this.sphere);
        if (intersects.length > 0) {
          const pt = intersects[0].point.clone().normalize();
          const pitch = THREE.MathUtils.radToDeg(Math.asin(Math.max(-1, Math.min(1, pt.y))));
          const yaw = THREE.MathUtils.radToDeg(Math.atan2(pt.z, pt.x));
          this.options.onPickPoint({
            yaw: Number(yaw.toFixed(1)),
            pitch: Number(pitch.toFixed(1)),
          });
        }
      }
    };

    this._onWheel = (e) => {
      e.preventDefault();
      this.fov = Math.max(35, Math.min(95, this.fov + e.deltaY * 0.04));
      this.camera.fov = this.fov;
      this.camera.updateProjectionMatrix();
    };

    this._onResize = () => this.resize();

    this._onDeviceOrientation = (event) => {
      if (!this.gyroEnabled || event.alpha === null) return;
      // Map alpha/beta smoothly to lon/lat
      const alpha = event.alpha || 0;
      const beta = event.beta || 90;
      this.lon = -alpha;
      this.lat = Math.max(-85, Math.min(85, beta - 90));
    };

    el.addEventListener('mousedown', this._onPointerDown);
    window.addEventListener('mousemove', this._onPointerMove);
    window.addEventListener('mouseup', this._onPointerUp);
    el.addEventListener('touchstart', this._onPointerDown, { passive: true });
    window.addEventListener('touchmove', this._onPointerMove, { passive: true });
    window.addEventListener('touchend', this._onPointerUp);
    el.addEventListener('wheel', this._onWheel, { passive: false });
    window.addEventListener('resize', this._onResize);
    window.addEventListener('deviceorientation', this._onDeviceOrientation);
  }

  resize() {
    const width = this.container.clientWidth || window.innerWidth;
    const height = this.container.clientHeight || window.innerHeight;
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(width, height);
  }

  loadPanorama(imageUrl, initialYaw = 0, hotspots = []) {
    this.lon = initialYaw;
    this.lat = 0;
    this.setHotspots(hotspots);

    return new Promise((resolve, reject) => {
      this.textureLoader.load(
        imageUrl,
        (texture) => {
          texture.colorSpace = THREE.SRGBColorSpace;
          if (this.material.map) this.material.map.dispose();
          this.material.map = texture;
          this.material.needsUpdate = true;
          resolve();
        },
        undefined,
        (err) => reject(err)
      );
    });
  }

  setHotspots(hotspots = []) {
    this.hotspots = hotspots;
    if (!this.hotspotsLayer) return;
    this.hotspotsLayer.innerHTML = '';
    this.hotspotElements = hotspots.map((hs) => {
      const el = document.createElement('div');
      el.className = 'hotspot-marker';
      el.innerHTML = `
        <div class="hotspot-dot" title="${hs.label || ''}">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <path d="M12 19V5M5 12l7-7 7 7"/>
          </svg>
        </div>
        <span class="hotspot-label">${hs.label || 'Pindah Ruangan'}</span>
      `;
      el.addEventListener('click', (ev) => {
        ev.stopPropagation();
        if (typeof this.options.onHotspotClick === 'function') {
          this.options.onHotspotClick(hs);
        }
      });
      this.hotspotsLayer.appendChild(el);
      return { data: hs, el };
    });
  }

  setAutoRotate(enabled) {
    this.autoRotate = Boolean(enabled);
  }

  setStereoMode(enabled) {
    this.stereoMode = Boolean(enabled);
    this.renderer.setScissorTest(this.stereoMode);
    if (!this.stereoMode) {
      const width = this.container.clientWidth || window.innerWidth;
      const height = this.container.clientHeight || window.innerHeight;
      this.renderer.setViewport(0, 0, width, height);
    }
  }

  async setGyroEnabled(enabled) {
    if (enabled && typeof DeviceOrientationEvent !== 'undefined' && typeof DeviceOrientationEvent.requestPermission === 'function') {
      const perm = await DeviceOrientationEvent.requestPermission();
      if (perm !== 'granted') {
        throw new Error('Izin sensor gyroscope ditolak.');
      }
    }
    this.gyroEnabled = Boolean(enabled);
  }

  _yawPitchToVector(yawDeg, pitchDeg, radius = 480) {
    const phi = THREE.MathUtils.degToRad(90 - pitchDeg);
    const theta = THREE.MathUtils.degToRad(yawDeg);
    return new THREE.Vector3(
      radius * Math.sin(phi) * Math.cos(theta),
      radius * Math.cos(phi),
      radius * Math.sin(phi) * Math.sin(theta)
    );
  }

  _updateHotspots() {
    if (!this.hotspotsLayer || this.stereoMode) {
      if (this.hotspotsLayer) this.hotspotsLayer.style.display = this.stereoMode ? 'none' : 'block';
      return;
    }
    const width = this.container.clientWidth;
    const height = this.container.clientHeight;
    const camDir = new THREE.Vector3();
    this.camera.getWorldDirection(camDir);

    for (const item of this.hotspotElements) {
      const pos = this._yawPitchToVector(item.data.yaw, item.data.pitch);
      const dirToPt = pos.clone().normalize();
      const dot = camDir.dot(dirToPt);

      if (dot <= 0.1) {
        item.el.style.display = 'none';
        continue;
      }

      const projected = pos.clone().project(this.camera);
      const x = (projected.x * 0.5 + 0.5) * width;
      const y = (-projected.y * 0.5 + 0.5) * height;
      item.el.style.display = 'flex';
      item.el.style.left = `${x}px`;
      item.el.style.top = `${y}px`;
    }
  }

  _animate() {
    this._rafId = requestAnimationFrame(() => this._animate());

    if (this.autoRotate && !this.isPointerDown && !this.gyroEnabled) {
      this.lon += 0.08;
    }

    const target = this._yawPitchToVector(this.lon, this.lat, 500);
    this.camera.position.set(0, 0, 0);
    this.camera.lookAt(target);

    if (typeof this.options.onYawChange === 'function') {
      const normalizedYaw = ((this.lon % 360) + 360) % 360;
      this.options.onYawChange(normalizedYaw);
    }

    if (this.stereoMode) {
      const width = this.container.clientWidth || window.innerWidth;
      const height = this.container.clientHeight || window.innerHeight;
      const halfW = Math.floor(width / 2);

      // Left eye
      this.cameraLeft.fov = this.fov;
      this.cameraLeft.aspect = halfW / height;
      this.cameraLeft.updateProjectionMatrix();
      this.cameraLeft.position.set(-0.032, 0, 0);
      this.cameraLeft.lookAt(target);
      this.renderer.setViewport(0, 0, halfW, height);
      this.renderer.setScissor(0, 0, halfW, height);
      this.renderer.render(this.scene, this.cameraLeft);

      // Right eye
      this.cameraRight.fov = this.fov;
      this.cameraRight.aspect = halfW / height;
      this.cameraRight.updateProjectionMatrix();
      this.cameraRight.position.set(0.032, 0, 0);
      this.cameraRight.lookAt(target);
      this.renderer.setViewport(halfW, 0, halfW, height);
      this.renderer.setScissor(halfW, 0, halfW, height);
      this.renderer.render(this.scene, this.cameraRight);
    } else {
      this.renderer.render(this.scene, this.camera);
    }

    this._updateHotspots();
  }

  dispose() {
    cancelAnimationFrame(this._rafId);
    window.removeEventListener('mousemove', this._onPointerMove);
    window.removeEventListener('mouseup', this._onPointerUp);
    window.removeEventListener('touchmove', this._onPointerMove);
    window.removeEventListener('touchend', this._onPointerUp);
    window.removeEventListener('resize', this._onResize);
    window.removeEventListener('deviceorientation', this._onDeviceOrientation);
    this.renderer.dispose();
  }
}

import { PanoViewer } from '/js/pano-viewer.js';

const projectNameEl = document.getElementById('project-name');
const roomSubtitleEl = document.getElementById('room-subtitle');
const floorplanImg = document.getElementById('floorplan-img');
const floorplanPinsEl = document.getElementById('floorplan-pins');
const radarConeEl = document.getElementById('radar-cone');
const radarSvgEl = document.getElementById('radar-svg');
const roomStripEl = document.getElementById('room-strip');
const minimapWidget = document.getElementById('minimap-widget');
const vrHud = document.getElementById('vr-overlay-hud');
const toastEl = document.getElementById('toast');

let currentProject = null;
let currentRoom = null;
let viewer = null;

function showToast(msg) {
  toastEl.textContent = msg;
  toastEl.classList.add('show');
  setTimeout(() => toastEl.classList.remove('show'), 2600);
}

function getRequestedSlug() {
  const params = new URLSearchParams(window.location.search);
  if (params.get('p')) return params.get('p');
  const match = window.location.pathname.match(/\/p\/([^/]+)/);
  if (match && match[1]) return decodeURIComponent(match[1]);
  return null;
}

function resolveAssetUrl(path) {
  if (!path) return '';
  if (path.startsWith('http://') || path.startsWith('https://') || path.startsWith('data:') || path.startsWith('/')) {
    return path;
  }
  return '/' + path;
}

function renderFloorplanPins() {
  if (!currentProject) return;
  const rooms = currentProject.rooms || [];
  floorplanPinsEl.innerHTML = '';

  rooms.forEach((room) => {
    if (typeof room.pinX !== 'number' || typeof room.pinY !== 'number') return;
    const pin = document.createElement('button');
    const isActive = currentRoom && currentRoom.id === room.id;
    pin.className = `floorplan-pin ${room.category || 'interior'} ${isActive ? 'active' : ''}`;
    pin.style.left = `${room.pinX}%`;
    pin.style.top = `${room.pinY}%`;
    pin.title = room.name;
    pin.innerHTML = `<span class="floorplan-pin-tooltip">${room.name}</span>`;
    pin.addEventListener('click', () => selectRoom(room.id));
    floorplanPinsEl.appendChild(pin);
  });

  if (currentRoom && typeof currentRoom.pinX === 'number' && typeof currentRoom.pinY === 'number') {
    radarConeEl.style.display = 'block';
    radarConeEl.style.left = `${currentRoom.pinX}%`;
    radarConeEl.style.top = `${currentRoom.pinY}%`;
  } else {
    radarConeEl.style.display = 'none';
  }
}

function renderRoomStrip() {
  if (!currentProject) return;
  const rooms = currentProject.rooms || [];
  roomStripEl.innerHTML = '';

  rooms.forEach((room) => {
    const btn = document.createElement('button');
    const isActive = currentRoom && currentRoom.id === room.id;
    btn.className = `room-chip ${isActive ? 'active' : ''}`;
    btn.innerHTML = `
      <span class="cat-dot ${room.category || 'interior'}"></span>
      <span>${room.name}</span>
    `;
    btn.addEventListener('click', () => selectRoom(room.id));
    roomStripEl.appendChild(btn);
  });
}

async function selectRoom(roomId) {
  if (!currentProject) return;
  const room = (currentProject.rooms || []).find((r) => r.id === roomId);
  if (!room) return;
  currentRoom = room;

  const catLabel = room.category === 'exterior' ? 'Exterior' : 'Interior';
  roomSubtitleEl.textContent = `${catLabel} • ${room.name}`;
  document.title = `${room.name} — ${currentProject.name}`;

  renderFloorplanPins();
  renderRoomStrip();

  try {
    await viewer.loadPanorama(
      resolveAssetUrl(room.panorama),
      room.initialYaw || 0,
      room.hotspots || []
    );
  } catch (err) {
    showToast('Gagal memuat foto 360° ruangan ini.');
  }
}

function bindControls() {
  const btnAuto = document.getElementById('btn-autorotate');
  const btnGyro = document.getElementById('btn-gyro');
  const btnVr = document.getElementById('btn-vr');
  const btnExitVr = document.getElementById('btn-exit-vr');
  const btnShare = document.getElementById('btn-share');
  const btnFullscreen = document.getElementById('btn-fullscreen');
  const btnExpand = document.getElementById('btn-minimap-expand');
  const btnToggle = document.getElementById('btn-minimap-toggle');

  btnAuto.addEventListener('click', () => {
    const next = !viewer.autoRotate;
    viewer.setAutoRotate(next);
    btnAuto.classList.toggle('active', next);
  });

  btnGyro.addEventListener('click', async () => {
    const next = !viewer.gyroEnabled;
    try {
      await viewer.setGyroEnabled(next);
      btnGyro.classList.toggle('active', next);
      showToast(next ? 'Sensor Gyroscope aktif' : 'Sensor Gyroscope dimatikan');
    } catch (err) {
      showToast(err.message || 'Perangkat tidak mendukung Gyroscope');
    }
  });

  const toggleVr = (enable) => {
    viewer.setStereoMode(enable);
    vrHud.classList.toggle('active', enable);
    document.getElementById('viewer-topbar').style.display = enable ? 'none' : 'flex';
    document.getElementById('viewer-bottombar').style.display = enable ? 'none' : 'flex';
    minimapWidget.style.display = enable ? 'none' : 'block';
    if (enable && document.documentElement.requestFullscreen) {
      document.documentElement.requestFullscreen().catch(() => {});
    }
  };

  btnVr.addEventListener('click', () => toggleVr(true));
  btnExitVr.addEventListener('click', () => toggleVr(false));

  btnShare.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
      showToast('Link tur 360° berhasil disalin!');
    } catch {
      showToast(window.location.href);
    }
  });

  btnFullscreen.addEventListener('click', () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(() => {});
    } else {
      document.exitFullscreen().catch(() => {});
    }
  });

  btnExpand.addEventListener('click', () => {
    minimapWidget.classList.toggle('expanded');
  });

  btnToggle.addEventListener('click', () => {
    const collapsed = minimapWidget.classList.toggle('collapsed');
    btnToggle.textContent = collapsed ? '+' : '−';
  });
}

async function init() {
  const container = document.getElementById('pano-canvas-container');
  const hotspotsLayer = document.getElementById('hotspots-layer');

  viewer = new PanoViewer(container, hotspotsLayer, {
    onHotspotClick: (hs) => {
      if (hs.targetRoomId) {
        selectRoom(hs.targetRoomId);
      }
    },
    onYawChange: (yawDeg) => {
      if (!currentRoom) return;
      const offset = Number(currentRoom.northOffset || 0);
      const angle = yawDeg + offset;
      radarSvgEl.style.transform = `rotate(${angle}deg)`;
    },
  });

  bindControls();

  try {
    const res = await fetch('/data/projects.json?t=' + Date.now());
    const data = await res.json();
    const projects = data.projects || [];
    const slug = getRequestedSlug();

    currentProject =
      projects.find((p) => p.slug === slug || p.id === slug) || projects[0];

    if (!currentProject) {
      projectNameEl.textContent = 'Projek tidak ditemukan';
      return;
    }

    projectNameEl.textContent = currentProject.name;
    if (currentProject.floorplan) {
      floorplanImg.src = resolveAssetUrl(currentProject.floorplan);
    } else {
      minimapWidget.style.display = 'none';
    }

    const startRoomId =
      currentProject.defaultRoomId ||
      (currentProject.rooms && currentProject.rooms[0] && currentProject.rooms[0].id);

    if (startRoomId) {
      await selectRoom(startRoomId);
    }
  } catch (err) {
    projectNameEl.textContent = 'Gagal memuat data projek';
    showToast(err.message);
  }
}

init();

import { PanoViewer } from '/js/pano-viewer.js';

const loginScreen = document.getElementById('login-screen');
const adminDashboard = document.getElementById('admin-dashboard');
const loginForm = document.getElementById('login-form');
const loginError = document.getElementById('login-error');
const toastEl = document.getElementById('toast');

let state = { projects: [] };
let activeProjectIdx = 0;
let activeRoomIdx = -1;
let editorViewer = null;

function showToast(msg) {
  toastEl.textContent = msg;
  toastEl.classList.add('show');
  setTimeout(() => toastEl.classList.remove('show'), 2800);
}

function slugify(str) {
  return String(str || '')
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'projek-' + Date.now();
}

function resolveAssetUrl(path) {
  if (!path) return '';
  if (path.startsWith('http://') || path.startsWith('https://') || path.startsWith('data:') || path.startsWith('/')) {
    return path;
  }
  return '/' + path;
}

function getActiveProject() {
  return state.projects[activeProjectIdx] || null;
}

function getActiveRoom() {
  const proj = getActiveProject();
  if (!proj || !proj.rooms) return null;
  return proj.rooms[activeRoomIdx] || null;
}

// ---------- Auth ----------
async function checkAuth() {
  try {
    const res = await fetch('/api/auth-check');
    if (res.ok) {
      const data = await res.json();
      if (data.authenticated) {
        await enterDashboard();
        return;
      }
    }
  } catch {
    // ignore
  }
  loginScreen.style.display = 'grid';
  adminDashboard.style.display = 'none';
}

loginForm.addEventListener('submit', async (e) => {
  e.preventDefault();
  loginError.style.display = 'none';
  const password = document.getElementById('admin-password').value;

  try {
    const res = await fetch('/api/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ password }),
    });
    const data = await res.json();
    if (!res.ok) {
      throw new Error(data.error || 'Password salah');
    }
    document.getElementById('admin-password').value = '';
    await enterDashboard();
  } catch (err) {
    loginError.textContent = err.message;
    loginError.style.display = 'block';
  }
});

document.getElementById('btn-logout').addEventListener('click', async () => {
  await fetch('/api/logout', { method: 'POST' });
  loginScreen.style.display = 'grid';
  adminDashboard.style.display = 'none';
});

async function enterDashboard() {
  loginScreen.style.display = 'none';
  adminDashboard.style.display = 'block';
  await loadProjects();
}

// ---------- Data Load & Save ----------
async function loadProjects() {
  const res = await fetch('/data/projects.json?t=' + Date.now());
  const data = await res.json();
  state = { projects: data.projects || [] };
  activeProjectIdx = state.projects.length ? 0 : -1;
  activeRoomIdx = -1;
  renderAll();
}

async function saveAllToServer() {
  try {
    const res = await fetch('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(state),
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Gagal menyimpan data');
    showToast(data.message || 'Semua projek berhasil disimpan!');
  } catch (err) {
    showToast('Error: ' + err.message);
  }
}

async function uploadFile(file, projectSlug) {
  const form = new FormData();
  form.append('file', file);
  form.append('slug', projectSlug || 'general');

  const res = await fetch('/api/upload', {
    method: 'POST',
    body: form,
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || 'Upload gagal');
  return data.path;
}

